// KrxErrorMapper.kt
package com.etfmonitor.core.data.krx.adapter

import com.krxkt.api.KrxError
import com.etfmonitor.core.util.AppError

object KrxErrorMapper {
    fun mapToAppError\(error: KrxError\): AppError = when \(error\) {
        is KrxError.NetworkError -> AppError.NetworkError\(error.message\)
        is KrxError.ServerError -> AppError.ServerError\(error.message\)
        is KrxError.ParseError -> AppError.DataError\(error.message\)
        is KrxError.InvalidParameter -> AppError.ValidationError\(error.message\)
    }
}
```

