package com.etfmonitor.core.data.krx.adapter

import java.time.LocalDate
import java.time.format.DateTimeFormatter

object DateAdapter {
    private val krxFormat = DateTimeFormatter.ofPattern\("yyyyMMdd"\)

    fun toKrxFormat\(date: LocalDate\): String = date.format\(krxFormat\)
    fun fromKrxFormat\(dateStr: String\): LocalDate = LocalDate.parse\(dateStr, krxFormat\)
