// KrxRepositoryBase.kt
package com.etfmonitor.core.data.krx.adapter

import com.krxkt.api.KrxError
import com.etfmonitor.core.util.AppError
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlinx.coroutines.withTimeout

abstract class KrxRepositoryBase {
    protected suspend fun <T> krxCall\(
        timeoutMs: Long = 30_000L,
        block: suspend \(\) -> T
    \): Result<T> = withContext\(Dispatchers.IO\) {
        try {
            withTimeout\(timeoutMs\) {
                Result.success\(block\(\)\)
            }
        } catch \(e: KrxError\) {
            Result.failure\(KrxErrorMapper.mapToAppError\(e\)\)
        } catch \(e: Exception\) {
            Result.failure\(AppError.UnknownError\(e.message ?: "Unknown error"\)\)
        }
    }
}
```

